import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int totalPoints = Integer.parseInt(br.readLine().trim());
        if (totalPoints >= 100) {
            out.print(0);
        } else {
            int[] coords1 = new int[105], coords2 = new int[105], coords3 = new int[105], coords4 = new int[105], coords5 = new int[105];
            for (int i = 1; i <= totalPoints; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                coords1[i] = Integer.parseInt(st.nextToken());
                coords2[i] = Integer.parseInt(st.nextToken());
                coords3[i] = Integer.parseInt(st.nextToken());
                coords4[i] = Integer.parseInt(st.nextToken());
                coords5[i] = Integer.parseInt(st.nextToken());
            }
            Set<Integer> invalid = new HashSet<>();
            for (int i = 1; i <= totalPoints; i++) {
                for (int j = 1; j <= totalPoints; j++) {
                    for (int k = 1; k <= totalPoints; k++) {
                        if (i == j || j == k || k == i) continue;
                        long diffA = coords1[j] - coords1[i], diffB = coords2[j] - coords2[i], diffC = coords3[j] - coords3[i], diffD = coords4[j] - coords4[i], diffE = coords5[j] - coords5[i];
                        long diffA2 = coords1[k] - coords1[i], diffB2 = coords2[k] - coords2[i], diffC2 = coords3[k] - coords3[i], diffD2 = coords4[k] - coords4[i], diffE2 = coords5[k] - coords5[i];
                        double dotProduct = diffA * diffA2 + diffB * diffB2 + diffC * diffC2 + diffD * diffD2 + diffE * diffE2;
                        long mag1 = diffA * diffA + diffB * diffB + diffC * diffC + diffD * diffD + diffE * diffE;
                        long mag2 = diffA2 * diffA2 + diffB2 * diffB2 + diffC2 * diffC2 + diffD2 * diffD2 + diffE2 * diffE2;
                        double cosine = dotProduct / Math.sqrt(mag1) / Math.sqrt(mag2);
                        if (Math.toDegrees(Math.acos(cosine)) + 1e-9 < 90) {
                            invalid.add(i);
                        }
                    }
                }
            }
            out.println(totalPoints - invalid.size());
            for (int i = 1; i <= totalPoints; i++) {
                if (!invalid.contains(i)) out.println(i);
            }
        }
        out.close();
    }
}
